Object.assign(AR.exact, {"Chat with the team": "تحدّث مع الفريق", "Write a message…": "اكتب رسالة…", "No messages yet. Say hello, ask a question, or send a photo.": "لا توجد رسائل بعد. ابدأ بالتحية أو اسأل سؤالًا أو أرسل صورة.", "You sent a lot of messages in a short time. Wait a few minutes, then try again.": "أرسلت رسائل كثيرة في وقت قصير. انتظر بضع دقائق ثم حاول مرة أخرى.", "Send pictures (JPG, PNG or WebP) or voice notes, up to 3 at a time.": "أرسل صورًا (JPG أو PNG أو WebP) أو رسائل صوتية، بحد أقصى 3 في المرة.", "Write a message first.": "اكتب رسالة أولًا.", "Add a photo": "أضف صورة", "Who answers this client": "مين بيرد على العميل ده", "They see this conversation and get its alerts. Admins can always see it.": "بيشوفوا المحادثة دي وبيجيلهم تنبيهاتها. الأدمنز يقدروا يشوفوها دايمًا.", "Choose": "اختار", "People at the client": "الأشخاص عند العميل", "Each person gets their own private link: they chat with you, see the status and report problems. Turn one off and only that link stops.": "كل شخص بياخد لينك خاص بيه: يكلمكم، ويتابع الشغل، ويبعت المشاكل. لو قفلت لينك واحد، هو بس اللي بيقف.", "Nobody yet.": "مفيش حد لسه.", "Ask an admin to add people.": "اطلب من أدمن يضيف أشخاص.", "Add a person": "أضف شخص", "Add and make their link": "أضفه واعمل اللينك بتاعه", "Adding…": "جارٍ الإضافة…", "Write the person’s name": "اكتب اسم الشخص", "Only admins can see the links": "الأدمنز بس اللي يشوفوا اللينكات", "Couldn’t open the conversation": "معرفناش نفتح المحادثة", "not opened yet": "لسه ما فتحش"});
AR.patterns.push(...[["^Messages go to the (.+?) team\\. They answer here\\.$", "رسائلك تصل إلى فريق $1، ويردّون عليك هنا."], ["^Client · (\\d+) (?:person|people) with a link · (\\d+) on our side$", "عميل · $1 معاهم لينك · $2 من عندنا"], ["^(.+?)’s link copied$", "اتنسخ لينك $1"], ["^(.+?)’s link is off$", "لينك $1 اتقفل"], ["^Link for (.+?) made and copied$", "اتعمل لينك $1 واتنسخ"], ["^Send (.+?) the link on WhatsApp\\?$", "تبعت لـ$1 اللينك على واتساب؟"], ["^Send (.+?) their link on WhatsApp$", "ابعت لـ$1 اللينك بتاعه على واتساب"], ["^last opened (.+?) ago$", "آخر فتح من $1"], ["^Remove attachment (\\d+)$", "احذف المرفق $1"], ["^Photo (\\d+)$", "صورة $1"]]);
